function articleToRagChunk(a) {
	const dose = a.dosage.map((d) => `${d.name}: ${d.range}. ${d.note}`).join(" | ");
	const mix = a.confuse.map((c) => `${c.lookalike} → ${c.difference}`).join(" | ");
	return [
		`SLUG ${a.slug}`,
		`TITLE ${a.title}`,
		`SEE ${a.phenomenon.appearance}`,
		`MIX ${mix}`,
		`STEPS ${a.solutions.steps.join(" / ")}`,
		`DONT ${a.dontDo.join(" / ")}`,
		`DOSE ${dose}`,
		`IND ${a.indicators.map((i) => `${i.name}:${i.typical}`).join(" / ")}`
	].join("\n");
}
function retrieveForRag(query, n = 6) {
	const hard = hardRoute(query).map(getArticle).filter((x) => !!x);
	const scored = filterArticles({ q: query }).map((a) => getArticle(a.slug)).filter((x) => !!x);
	const seen = /* @__PURE__ */ new Set();
	const out = [];
	for (const a of [...hard, ...scored]) {
		if (seen.has(a.slug)) continue;
		seen.add(a.slug);
		out.push(a);
		if (out.length >= n) break;
	}
	return out;
}
