	if (n.includes("ph")) return "ph";
	if (n.includes("esp") || n.includes("sar") || n.includes("碱化度") || n.includes("钠吸附")) return "esp";
	if (n.includes("交换性钠") || n.includes("ex-na") || n.includes("exna")) return "na";
